INSERT INTO public."prompts" ("id", "title", "description", "category", "category_color", "tags", "content", "difficulty", "is_favorite", "created_at", "updated_at", "search_vector") VALUES (2, '코드 리뷰 요청 프롬프트', '효과적인 코드 리뷰를 받기 위해서는 코드의 목적, 사용된 기술 스택, 특별히 검토받고 싶은 부분을 명확히 제시해야 합니다. 보안, 성능, 가독성 등 검토 포인트를 구체화하세요.', '코딩', 'bg-[#e0f4bf] border-[#cbec95]', '["리뷰","디버깅","최적화"]'::jsonb, '코드 리뷰 요청 프롬프트 템플릿:

