INSERT INTO public."prompts" ("id", "title", "description", "category", "category_color", "tags", "content", "difficulty", "is_favorite", "created_at", "updated_at", "search_vector") VALUES (3, '블로그 글 작성 프롬프트', 'SEO 친화적이고 독자의 관심을 끄는 블로그 글을 작성하려면 타겟 독자, 톤앤매너, 글의 목적을 명확히 설정하세요. 키워드, 글자 수, 구조도 함께 제시하면 더욱 효과적입니다.', '글쓰기', 'bg-[#feec91] border-[#fedf47]', '["블로그","SEO","콘텐츠"]'::jsonb, '블로그 글 작성 프롬프트 템플릿:

