INSERT INTO public."prompts" ("id", "title", "description", "category", "category_color", "tags", "content", "difficulty", "is_favorite", "created_at", "updated_at", "search_vector") VALUES (6, '창의적인 컨셉 아트 생성', '판타지, SF 등 창의적인 컨셉 아트를 만들 때는 분위기, 색상 팔레트, 아트 스타일을 구체적으로 설명하세요. 유명 아티스트 스타일을 레퍼런스로 제시하는 것도 효과적입니다.', '이미지 생성', 'bg-[#cae3ff] border-[#a6d1ff]', '["컨셉아트","판타지","스타일"]'::jsonb, '컨셉 아트 프롬프트 템플릿:

